-- Additive operational finance. Monetary values are integer minor units, never floats.
-- Shared actor/tenant/branch boundaries and the existing transactional outbox are retained.
create domain public.money_minor as bigint check(value between 0 and 9000000000000);
create domain public.rate_bps as integer check(value between 0 and 10000);

do $ddl$
declare r record; begin
 for r in select * from (values
 ('finance_settings', 'advances_deductible boolean not null default false, unique(organization_id)'),
 ('payment_methods', 'name text not null check(length(name) between 1 and 80), code text not null check(code ~ ''^[a-z0-9][a-z0-9_-]{1,62}$''), type text not null check(type in (''cash'',''bank'',''card'',''other'')), active boolean not null default true, unique(organization_id,code)'),
 ('payment_method_fee_rules', 'payment_method_id uuid not null, percentage_bps public.rate_bps not null, fixed_amount_minor public.money_minor not null default 0, effective_from timestamptz not null, effective_to timestamptz, active boolean not null default true, check(effective_to is null or effective_to>effective_from), foreign key(organization_id,payment_method_id) references public.payment_methods(organization_id,id), exclude using gist(payment_method_id with =, tstzrange(effective_from,effective_to,''[)'') with &&) where(active)'),
 ('commission_rules', 'staff_id uuid not null, service_id uuid not null, branch_id uuid, branch_scope uuid generated always as(coalesce(branch_id,''00000000-0000-0000-0000-000000000000''::uuid)) stored, rate_bps public.rate_bps not null, effective_from timestamptz not null, effective_to timestamptz, active boolean not null default true, check(effective_to is null or effective_to>effective_from), foreign key(organization_id,staff_id) references public.staff(organization_id,id), foreign key(organization_id,service_id) references public.services(organization_id,id), foreign key(organization_id,branch_id) references public.branches(organization_id,id), exclude using gist(staff_id with =,service_id with =,branch_scope with =,tstzrange(effective_from,effective_to,''[)'') with &&) where(active)'),
 ('finance_items', 'name text not null check(length(name) between 1 and 120), kind text not null check(kind in (''product'',''course'',''other'')), price_minor public.money_minor, active boolean not null default true'),
 ('expense_categories', 'name text not null check(length(name) between 1 and 80), code text not null check(code ~ ''^[a-z0-9][a-z0-9_-]{1,62}$''), kind text not null check(kind in (''operating'',''advance'',''salary'',''commission_payment'')), active boolean not null default true, unique(organization_id,code)'),
 ('cash_sessions', 'branch_id uuid not null, register_code text not null default ''principal'' check(length(register_code) between 1 and 40), local_date date not null, currency text not null check(currency ~ ''^[A-Z]{3}$''), status text not null default ''open'' check(status in (''opening'',''open'',''closing'',''closed'')), opening_amount_minor public.money_minor not null, expected_cash_minor bigint, actual_cash_minor public.money_minor, difference_minor bigint, reason text check(length(reason)<=500), opened_at timestamptz not null default now(), closed_at timestamptz, closed_by uuid references public.profiles(id), reopened_from_id uuid, snapshot jsonb, unique(organization_id,branch_id,id), foreign key(organization_id,branch_id) references public.branches(organization_id,id), foreign key(organization_id,reopened_from_id) references public.cash_sessions(organization_id,id), check((status=''closed'')=(closed_at is not null))'),
 ('checkouts', 'branch_id uuid not null, appointment_id uuid, customer_id uuid, staff_id uuid, currency text not null check(currency ~ ''^[A-Z]{3}$''), status text not null default ''draft'' check(status in (''draft'',''posted'',''reversed'',''voided'')), total_minor public.money_minor not null default 0, occurred_at timestamptz not null default now(), posted_at timestamptz, reversed_at timestamptz, replacement_for_id uuid, imported boolean not null default false, description text check(length(description)<=500), unique(organization_id,branch_id,id), foreign key(organization_id,branch_id) references public.branches(organization_id,id), foreign key(organization_id,appointment_id) references public.appointments(organization_id,id), foreign key(organization_id,customer_id) references public.customers(organization_id,id), foreign key(organization_id,staff_id) references public.staff(organization_id,id), foreign key(organization_id,replacement_for_id) references public.checkouts(organization_id,id)'),
 ('checkout_lines', 'branch_id uuid not null, checkout_id uuid not null, service_id uuid, item_id uuid, staff_id uuid, kind text not null check(kind in (''service'',''product'',''course'',''other'',''adjustment'')), name_snapshot text not null check(length(name_snapshot) between 1 and 120), staff_name_snapshot text, quantity integer not null check(quantity between 1 and 1000), unit_price_minor public.money_minor not null, amount_minor public.money_minor not null, currency text not null, metadata jsonb not null default ''{}'', check(amount_minor=unit_price_minor*quantity), check(service_id is null or item_id is null), foreign key(organization_id,branch_id,checkout_id) references public.checkouts(organization_id,branch_id,id), foreign key(organization_id,service_id) references public.services(organization_id,id), foreign key(organization_id,item_id) references public.finance_items(organization_id,id), foreign key(organization_id,staff_id) references public.staff(organization_id,id)'),
 ('payments', 'branch_id uuid not null, checkout_id uuid not null, payment_method_id uuid not null, amount_minor public.money_minor not null check(amount_minor>0), fee_minor public.money_minor, fee_rule_id uuid, percentage_bps public.rate_bps, fixed_amount_minor public.money_minor, fee_status text not null default ''known'' check(fee_status in (''known'',''unknown'')), method_name_snapshot text not null, method_type_snapshot text not null, direction integer not null default 1 check(direction in (-1,1)), reversal_of_id uuid, cash_session_id uuid, occurred_at timestamptz not null default now(), reference text check(length(reference)<=120), unique(organization_id,reversal_of_id), foreign key(organization_id,branch_id,checkout_id) references public.checkouts(organization_id,branch_id,id), foreign key(organization_id,payment_method_id) references public.payment_methods(organization_id,id), foreign key(organization_id,fee_rule_id) references public.payment_method_fee_rules(organization_id,id), foreign key(organization_id,reversal_of_id) references public.payments(organization_id,id), foreign key(organization_id,branch_id,cash_session_id) references public.cash_sessions(organization_id,branch_id,id), check((direction=-1)=(reversal_of_id is not null)), check((fee_status=''unknown'')=(fee_minor is null)), check(fee_minor is null or fee_minor<=amount_minor)'),
 ('expenses', 'branch_id uuid not null, category_id uuid not null, category_kind_snapshot text not null check(category_kind_snapshot in (''operating'',''advance'',''salary'',''commission_payment'')), staff_id uuid, vendor text check(length(vendor)<=120), description text not null check(length(description) between 1 and 500), amount_minor public.money_minor not null check(amount_minor>0), payment_method_id uuid not null, method_name_snapshot text not null, method_type_snapshot text not null, cash_session_id uuid, currency text not null, occurred_at timestamptz not null default now(), receipt_reference text check(length(receipt_reference)<=250), status text not null default ''posted'' check(status in (''posted'',''reversed'')), reversed_at timestamptz, imported boolean not null default false, unique(organization_id,branch_id,id), foreign key(organization_id,branch_id) references public.branches(organization_id,id), foreign key(organization_id,category_id) references public.expense_categories(organization_id,id), foreign key(organization_id,staff_id) references public.staff(organization_id,id), foreign key(organization_id,payment_method_id) references public.payment_methods(organization_id,id), foreign key(organization_id,branch_id,cash_session_id) references public.cash_sessions(organization_id,branch_id,id), check(category_kind_snapshot=''operating'' or staff_id is not null)'),
 ('commission_entries', 'branch_id uuid not null, staff_id uuid not null, service_id uuid, checkout_id uuid not null, checkout_line_id uuid not null, rule_id uuid, eligible_amount_minor public.money_minor not null, rate_bps public.rate_bps, amount_minor public.money_minor, calculation_status text not null check(calculation_status in (''known'',''unknown'')), direction integer not null default 1 check(direction in (-1,1)), reversal_of_id uuid, occurred_at timestamptz not null, snapshot jsonb not null, unique(organization_id,reversal_of_id), foreign key(organization_id,branch_id,checkout_id) references public.checkouts(organization_id,branch_id,id), foreign key(organization_id,checkout_line_id) references public.checkout_lines(organization_id,id), foreign key(organization_id,staff_id) references public.staff(organization_id,id), foreign key(organization_id,service_id) references public.services(organization_id,id), foreign key(organization_id,rule_id) references public.commission_rules(organization_id,id), foreign key(organization_id,reversal_of_id) references public.commission_entries(organization_id,id), check((calculation_status=''unknown'')=(amount_minor is null)), check((direction=-1)=(reversal_of_id is not null))'),
 ('staff_advances', 'branch_id uuid not null, staff_id uuid not null, expense_id uuid not null, deductible boolean not null, amount_minor public.money_minor not null, occurred_at timestamptz not null, foreign key(organization_id,branch_id,expense_id) references public.expenses(organization_id,branch_id,id), foreign key(organization_id,staff_id) references public.staff(organization_id,id), unique(organization_id,expense_id)'),
 ('salary_payments', 'branch_id uuid not null, staff_id uuid not null, expense_id uuid not null, amount_minor public.money_minor not null, occurred_at timestamptz not null, foreign key(organization_id,branch_id,expense_id) references public.expenses(organization_id,branch_id,id), foreign key(organization_id,staff_id) references public.staff(organization_id,id), unique(organization_id,expense_id)'),
 ('staff_settlements', 'branch_id uuid not null, staff_id uuid not null, period_start date not null, period_end date not null, status text not null default ''draft'' check(status in (''draft'',''reviewed'',''paid'',''closed'')), commission_accrued_minor bigint not null, advances_applied_minor public.money_minor not null default 0, adjustments_minor bigint not null default 0, commission_paid_minor public.money_minor not null default 0, remaining_balance_minor bigint not null, reviewed_at timestamptz, paid_at timestamptz, closed_at timestamptz, expense_id uuid, foreign key(organization_id,branch_id) references public.branches(organization_id,id), foreign key(organization_id,staff_id) references public.staff(organization_id,id), foreign key(organization_id,expense_id) references public.expenses(organization_id,id), check(period_end>=period_start), check(remaining_balance_minor=commission_accrued_minor-advances_applied_minor+adjustments_minor-commission_paid_minor)'),
 ('settlement_commission_entries', 'branch_id uuid not null, staff_id uuid not null, settlement_id uuid not null, commission_entry_id uuid not null, foreign key(organization_id,branch_id) references public.branches(organization_id,id), foreign key(organization_id,staff_id) references public.staff(organization_id,id), foreign key(organization_id,settlement_id) references public.staff_settlements(organization_id,id), foreign key(organization_id,commission_entry_id) references public.commission_entries(organization_id,id), unique(organization_id,commission_entry_id)'),
 ('settlement_advances', 'branch_id uuid not null, staff_id uuid not null, settlement_id uuid not null, advance_id uuid not null, amount_minor public.money_minor not null check(amount_minor>0), foreign key(organization_id,branch_id) references public.branches(organization_id,id), foreign key(organization_id,staff_id) references public.staff(organization_id,id), foreign key(organization_id,settlement_id) references public.staff_settlements(organization_id,id), foreign key(organization_id,advance_id) references public.staff_advances(organization_id,id), unique(organization_id,settlement_id,advance_id)'),
 ('financial_adjustments', 'branch_id uuid not null, staff_id uuid not null, amount_minor bigint not null check(amount_minor<>0 and abs(amount_minor)<=9000000000000), reason text not null check(length(reason) between 3 and 500), settlement_id uuid, occurred_at timestamptz not null default now(), foreign key(organization_id,branch_id) references public.branches(organization_id,id), foreign key(organization_id,staff_id) references public.staff(organization_id,id), foreign key(organization_id,settlement_id) references public.staff_settlements(organization_id,id)'),
 ('financial_reversals', 'branch_id uuid not null, entity_type text not null check(entity_type in (''checkout'',''payment'',''expense'')), entity_id uuid not null, reason text not null check(length(reason) between 3 and 500), occurred_at timestamptz not null default now(), foreign key(organization_id,branch_id) references public.branches(organization_id,id), unique(organization_id,entity_type,entity_id)'),
 ('cash_movements', 'branch_id uuid not null, cash_session_id uuid not null, kind text not null check(kind in (''payment'',''expense'',''refund'',''expense_reversal'',''adjustment'')), amount_minor bigint not null check(amount_minor<>0 and abs(amount_minor)<=9000000000000), payment_id uuid, expense_id uuid, reason text check(length(reason)<=500), occurred_at timestamptz not null default now(), foreign key(organization_id,branch_id,cash_session_id) references public.cash_sessions(organization_id,branch_id,id), foreign key(organization_id,payment_id) references public.payments(organization_id,id), foreign key(organization_id,expense_id) references public.expenses(organization_id,id), unique(organization_id,payment_id)'),
 ('daily_closures', 'branch_id uuid not null, local_date date not null, revision integer not null check(revision>0), cash_session_id uuid not null, snapshot jsonb not null, foreign key(organization_id,branch_id,cash_session_id) references public.cash_sessions(organization_id,branch_id,id), unique(organization_id,cash_session_id), unique(organization_id,branch_id,local_date,revision)'),
 ('finance_import_batches', 'branch_id uuid not null, source_file text not null check(length(source_file) between 1 and 250), source_sha256 text not null check(source_sha256 ~ ''^[0-9a-f]{64}$''), status text not null default ''preview'' check(status in (''preview'',''imported'')), mapping jsonb not null, preview_hash text not null, imported_at timestamptz, foreign key(organization_id,branch_id) references public.branches(organization_id,id), unique(organization_id,source_sha256)'),
 ('finance_import_rows', 'branch_id uuid not null, batch_id uuid not null, source_sheet text not null, source_row integer not null check(source_row>1), raw_values jsonb not null, normalized jsonb not null, anomalies jsonb not null, review_status text not null check(review_status in (''READY'',''NEEDS_REVIEW'',''EXCLUDED'',''IMPORTED'')), checkout_id uuid, expense_id uuid, foreign key(organization_id,branch_id) references public.branches(organization_id,id), foreign key(organization_id,batch_id) references public.finance_import_batches(organization_id,id), foreign key(organization_id,checkout_id) references public.checkouts(organization_id,id), foreign key(organization_id,expense_id) references public.expenses(organization_id,id), unique(organization_id,batch_id,source_sheet,source_row)'),
 ('daily_financial_metrics', 'branch_id uuid not null, local_date date not null, gross_revenue_minor bigint not null default 0, collected_minor bigint not null default 0, refunds_minor bigint not null default 0, expenses_minor bigint not null default 0, operating_expenses_minor bigint not null default 0, payment_processing_fees_minor bigint not null default 0, barber_commissions_minor bigint not null default 0, paid_checkouts integer not null default 0, unknown_fees integer not null default 0, unknown_commissions integer not null default 0, foreign key(organization_id,branch_id) references public.branches(organization_id,id), unique(organization_id,branch_id,local_date)'),
 ('daily_payment_method_metrics', 'branch_id uuid not null, payment_method_id uuid not null, local_date date not null, gross_received_minor bigint not null default 0, refunds_minor bigint not null default 0, expenses_minor bigint not null default 0, fee_minor bigint not null default 0, unknown_fees integer not null default 0, foreign key(organization_id,branch_id) references public.branches(organization_id,id), foreign key(organization_id,payment_method_id) references public.payment_methods(organization_id,id), unique(organization_id,branch_id,payment_method_id,local_date)'),
 ('daily_staff_financial_metrics', 'branch_id uuid not null, staff_id uuid not null, local_date date not null, gross_production_minor bigint not null default 0, paid_checkouts integer not null default 0, commission_accrued_minor bigint not null default 0, advances_minor bigint not null default 0, commission_paid_minor bigint not null default 0, salary_payments_minor bigint not null default 0, unknown_commissions integer not null default 0, foreign key(organization_id,branch_id) references public.branches(organization_id,id), foreign key(organization_id,staff_id) references public.staff(organization_id,id), unique(organization_id,branch_id,staff_id,local_date)')
 ) specs(name,columns) loop
 execute format('create table public.%I (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid default auth.uid() references public.profiles(id), unique(organization_id,id), %s)',r.name,r.columns);
 execute format('alter table public.%I enable row level security',r.name);
 execute format('revoke all on public.%I from public,anon,authenticated',r.name);
 execute format('grant select on public.%I to authenticated',r.name);
 execute format('create trigger protect_record before insert or update on public.%I for each row execute function app_private.touch_and_protect_tenant()',r.name);
 end loop;
end $ddl$;
alter table public.payment_method_fee_rules add column evidence_reference text check(length(evidence_reference) between 5 and 250);
alter table public.commission_rules add column evidence_reference text check(length(evidence_reference) between 5 and 250);

create table public.settlement_adjustments (
 id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id),
 branch_id uuid not null, staff_id uuid not null, settlement_id uuid not null, adjustment_id uuid not null,
 created_at timestamptz not null default now(), unique(organization_id,id), unique(organization_id,adjustment_id),
 foreign key(organization_id,branch_id) references public.branches(organization_id,id),
 foreign key(organization_id,staff_id) references public.staff(organization_id,id),
 foreign key(organization_id,settlement_id) references public.staff_settlements(organization_id,id),
 foreign key(organization_id,adjustment_id) references public.financial_adjustments(organization_id,id)
);
alter table public.settlement_adjustments enable row level security;
revoke all on public.settlement_adjustments from public,anon,authenticated;
grant select on public.settlement_adjustments to authenticated;

create unique index one_active_checkout_per_appointment on public.checkouts(organization_id,appointment_id) where appointment_id is not null and status in ('draft','posted');
create unique index one_open_cash_register on public.cash_sessions(organization_id,branch_id,register_code) where status<>'closed';
create unique index one_commission_per_line on public.commission_entries(organization_id,checkout_line_id) where direction=1;
create index finance_checkout_period on public.checkouts(organization_id,branch_id,posted_at,id);
create index finance_checkout_pending on public.checkouts(organization_id,branch_id,occurred_at,id) where status='draft';
create index finance_payment_period on public.payments(organization_id,branch_id,occurred_at,id);
create index finance_expense_period on public.expenses(organization_id,branch_id,occurred_at,id);
create index finance_commission_period on public.commission_entries(organization_id,branch_id,staff_id,occurred_at,id);

create function app_private.finance_access(p_org uuid,p_branch uuid,p_level text default 'report') returns boolean language sql stable security definer set search_path='' as $$
 select app_private.current_profile() is not null and app_private.is_org_member(p_org) and
 (p_branch is null or exists(select 1 from public.branches where organization_id=p_org and id=p_branch)) and
 (app_private.has_org_role(p_org,array['organization_owner','finance']) or
  (p_branch is not null and app_private.can_access_branch(p_org,p_branch) and
   (app_private.has_org_role(p_org,array['manager']) or (p_level='operate' and app_private.has_org_role(p_org,array['receptionist']))))) $$;
create function app_private.finance_staff_access(p_org uuid,p_branch uuid,p_staff uuid) returns boolean language sql stable security definer set search_path='' as $$
 select app_private.finance_access(p_org,p_branch,'report') or
 (p_staff=app_private.current_staff_id(p_org) and app_private.can_access_branch(p_org,p_branch)) $$;
create function app_private.finance_checkout_access(p_org uuid,p_checkout uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.checkouts where organization_id=p_org and id=p_checkout and app_private.finance_access(p_org,branch_id,'operate')) $$;
revoke all on function app_private.finance_access(uuid,uuid,text),app_private.finance_staff_access(uuid,uuid,uuid),app_private.finance_checkout_access(uuid,uuid) from public,anon,authenticated;
grant execute on function app_private.finance_access(uuid,uuid,text),app_private.finance_staff_access(uuid,uuid,uuid),app_private.finance_checkout_access(uuid,uuid) to authenticated;

do $rls$ declare t text; begin
 foreach t in array array['finance_settings','payment_methods','finance_items','expense_categories'] loop
 execute format('create policy finance_catalog_read on public.%I for select to authenticated using(app_private.is_org_member(organization_id))',t);
 end loop;
 create policy fee_rules_read on public.payment_method_fee_rules for select to authenticated using(app_private.has_org_role(organization_id,array['organization_owner','finance']));
 create policy commission_rules_read on public.commission_rules for select to authenticated using(app_private.has_org_role(organization_id,array['organization_owner','finance']) or (branch_id is not null and app_private.finance_access(organization_id,branch_id,'report')));
 foreach t in array array['checkouts','payments','cash_sessions','cash_movements'] loop
 execute format('create policy finance_operational_read on public.%I for select to authenticated using(app_private.finance_access(organization_id,branch_id,''operate''))',t);
 end loop;
 create policy checkout_lines_read on public.checkout_lines for select to authenticated using(app_private.finance_checkout_access(organization_id,checkout_id));
 create policy expense_read on public.expenses for select to authenticated using(app_private.finance_access(organization_id,branch_id,'report') or (category_kind_snapshot='operating' and app_private.finance_access(organization_id,branch_id,'operate')));
 foreach t in array array['commission_entries','staff_advances','salary_payments','staff_settlements','settlement_commission_entries','settlement_advances','financial_adjustments','daily_staff_financial_metrics'] loop
 execute format('create policy own_finance_read on public.%I for select to authenticated using(app_private.finance_staff_access(organization_id,branch_id,staff_id))',t);
 end loop;
 foreach t in array array['daily_closures','financial_reversals','daily_financial_metrics','daily_payment_method_metrics'] loop
 execute format('create policy finance_report_read on public.%I for select to authenticated using(app_private.finance_access(organization_id,branch_id,''report''))',t);
 end loop;
 foreach t in array array['finance_import_batches','finance_import_rows'] loop
 execute format('create policy financial_import_read on public.%I for select to authenticated using(app_private.has_org_role(organization_id,array[''organization_owner'',''finance'']))',t);
 end loop;
 foreach t in array array['payments','commission_entries','staff_advances','salary_payments','settlement_commission_entries','settlement_advances','financial_adjustments','financial_reversals','cash_movements','daily_closures'] loop
 execute format('create trigger financial_append_only before update or delete on public.%I for each row execute function app_private.deny_history_mutation()',t);
 end loop;
end $rls$;
create policy own_finance_read on public.settlement_adjustments for select to authenticated using(app_private.finance_staff_access(organization_id,branch_id,staff_id));
create trigger financial_append_only before update or delete on public.settlement_adjustments for each row execute function app_private.deny_history_mutation();

-- Tenant and immutable snapshots are protected even against accidental privileged SQL.
create function app_private.finance_guard() returns trigger language plpgsql set search_path='' as $$
declare v jsonb:=to_jsonb(old); n jsonb:=to_jsonb(new); begin
 if tg_op='DELETE' then raise exception 'financial_delete_forbidden' using errcode='42501'; end if;
 if (tg_table_name='finance_import_batches' and v->>'status'='imported') or (tg_table_name='finance_import_rows' and v->>'review_status'='IMPORTED') then raise exception 'financial_import_sealed' using errcode='42501';end if;
 if tg_table_name in ('checkouts','expenses','cash_sessions','staff_settlements') then
 if v->>'status' in ('reversed','voided','closed') then raise exception 'financial_record_sealed' using errcode='42501'; end if;
 if tg_table_name in ('checkouts','expenses') and v->>'status'='posted' and n->>'status'<>'reversed' then raise exception 'invalid_financial_transition' using errcode='23514'; end if;
 if tg_table_name='staff_settlements' and ((v->>'status'='reviewed' and n->>'status'<>'paid') or (v->>'status'='paid' and n->>'status'<>'closed')) then raise exception 'invalid_settlement_transition' using errcode='23514'; end if;
 if v->>'status' in ('posted','paid','reviewed') and (to_jsonb(new)-array['status','updated_at','reversed_at','commission_paid_minor','remaining_balance_minor','paid_at','closed_at','expense_id']) is distinct from (v-array['status','updated_at','reversed_at','commission_paid_minor','remaining_balance_minor','paid_at','closed_at','expense_id']) then raise exception 'financial_snapshot_immutable' using errcode='42501'; end if;
 elsif tg_table_name='checkout_lines' then
 if exists(select 1 from public.checkouts where organization_id=old.organization_id and id=old.checkout_id and status<>'draft') then raise exception 'financial_snapshot_immutable' using errcode='42501'; end if;
 elsif tg_table_name in ('payment_method_fee_rules','commission_rules') then
 if (n-array['effective_to','updated_at','branch_scope']) is distinct from (v-array['effective_to','updated_at','branch_scope']) or new.effective_to is null or new.effective_to<=old.effective_from or (old.effective_to is not null and new.effective_to>old.effective_to) then raise exception 'financial_rule_version_required' using errcode='42501'; end if;
 end if;
 return new;
end $$;
revoke all on function app_private.finance_guard() from public,anon,authenticated;
do $$ declare t text;begin foreach t in array array['checkouts','checkout_lines','expenses','cash_sessions','staff_settlements','payment_method_fee_rules','commission_rules','finance_import_batches','finance_import_rows'] loop
 execute format('create trigger finance_seal before update or delete on public.%I for each row execute function app_private.finance_guard()',t); end loop; end $$;
revoke insert,update,delete on public.visits from public,anon,authenticated;

-- Every new FK gets an index only if no existing index covers its leading columns.
do $$ declare r record; cols text; begin
 for r in select c.conrelid,c.conname,c.conkey from pg_constraint c join pg_namespace n on n.oid=(select relnamespace from pg_class where oid=c.conrelid) where c.contype='f' and n.nspname='public' loop
 if not exists(select 1 from pg_index i where i.indrelid=r.conrelid and i.indisvalid and array(select unnest(i.indkey::smallint[]) limit cardinality(r.conkey))=r.conkey) then
 select string_agg(quote_ident(a.attname),',' order by k.ord) into cols from unnest(r.conkey) with ordinality k(num,ord) join pg_attribute a on a.attrelid=r.conrelid and a.attnum=k.num;
 execute format('create index %I on %s (%s)',left(r.conname,49)||'_fin_idx',r.conrelid::regclass,cols); end if;end loop;end $$;
